//! The JSON Schema of the server's configuration file, generated from [`ServerConfig`].
//!
//! The schema is the file's grammar stated a second time, so it is generated from the type
//! that reads the file rather than written beside it. It is committed as generated by a
//! build with every feature on, so it names every key any build reads.

use std::sync::OnceLock;

use serde_json::Value;

use super::ServerConfig;

/// Where the schema is committed, from the repository root.
pub const SERVER_CONFIG_JSON_SCHEMA_PATH: &str = "docs/schemas/fraiseql-server.schema.json";

/// The schema's URL for this release: the committed file at the release's tag. It is the
/// schema's `$id`.
#[must_use]
pub fn server_config_json_schema_url() -> String {
    format!(
        "https://raw.githubusercontent.com/fraiseql/fraiseql/v{}/{SERVER_CONFIG_JSON_SCHEMA_PATH}",
        env!("CARGO_PKG_VERSION")
    )
}

/// The JSON Schema an editor checks the server's configuration file against, as this build
/// reads it.
#[must_use]
pub fn server_config_json_schema() -> Value {
    schema().clone()
}

fn schema() -> &'static Value {
    static SCHEMA: OnceLock<Value> = OnceLock::new();
    SCHEMA.get_or_init(|| {
        let mut schema =
            serde_json::to_value(schemars::schema_for!(ServerConfig)).unwrap_or_default();
        schema["$id"] = Value::String(server_config_json_schema_url());
        schema["title"] = Value::String("FraiseQL server configuration".to_owned());
        schema["description"] = Value::String(
            "The file the FraiseQL server reads at boot, named by `--config` or \
             `FRAISEQL_CONFIG`."
                .to_owned(),
        );
        schema
    })
}

